function sunTracks(data){return KPTransitEventChains.sunTracks(Object.fromEntries(['MD','AD','PD'].map(k=>[k,data.periods[k].id])),currentKPModel,last?.ruling,last?.rulingModel).tracks;}
function candidatesView(){const box=$('tr-event-candidates');if(!box)return;box.replaceChildren();if(last?.mode!=='event')return;const heading=document.createElement('h3');heading.textContent=text('Transit Reader · rule matches','ट्रान्झिट रीडर · नियमाशी जुळणारे कालावधी');const p=document.createElement('p');p.textContent=text('All nine planets are scanned through event-significator nakshatra AND sub lords over the selected dates. DBA supplies the date range only; it does not filter transit matches. Results are grouped by local entry date; intervals may continue beyond that day.','निवडलेल्या तारखांत सर्व नऊ ग्रहांचे गोचर कार्येशांच्या नक्षत्र व उपातून तपासले जाते. दशेतून फक्त तारखा घेतल्या जातात; गोचर पात्रतेसाठी दशेची अट नाही.');box.append(heading,p);if(last.allSignificators){const note=document.createElement('p');note.textContent=text('All nine planets qualify: this rule accepts every star/sub sector, so it cannot identify one unique event date.','सर्व नऊ ग्रह कार्येश आहेत: प्रत्येक नक्षत्र/उप विभाग पात्र ठरतो; या नियमातून एकच निश्चित घटना दिनांक वेगळा करता येत नाही.');box.append(note);}if(last.excluded?.length){const note=document.createElement('p');note.textContent=text('Selected planets excluded because they are not event significators: ','घटनेचे कार्येश नसल्यामुळे वगळलेले निवडलेले ग्रह: ')+last.excluded.join(', ');box.append(note);}}
