function evidence(){if(!$('tr-auto-evidence'))return;const box=$('tr-auto-evidence');if(!last){box.replaceChildren();return;}if(last.mode==='event'){box.innerHTML='<details><summary>'+esc(text('Transit Reader evidence','ट्रान्झिट रीडर आधार'))+'</summary><p>'+esc(last.start+' → '+last.end+' · Event significators: '+last.significators.join(', '))+'</p><p>All nine moving planets; nakshatra lord AND sub lord are event significators. DBA supplies dates only. No DBA eligibility, Rashi, transit-house or RP filter.</p></details>';return;}const rp=last.ruling,rulers=KPTransitEventChains.lsrd(rp),unpaired=KPTransitEventChains.unpaired(currentKPModel);box.innerHTML='<details><summary>'+esc(text('Automatic DBA and chain evidence','स्वयंचलित DBA व साखळीचा आधार'))+'</summary><p>'+esc(last.start+' → '+last.end+' · '+last.periodCount+' event-supported DBA windows · '+last.significators.join(', '))+'</p><p>'+esc('LSRD '+rulers.map(p=>p.rank+': '+p.id).join(' > ')+' · Query '+rp.utc+' · '+rp.location.place)+'</p><details><summary>'+esc(text('Pairs requiring LSRD fallback','LSRD आवश्यक असलेल्या जोड्या'))+' · '+unpaired.length+'</summary><p>'+esc(unpaired.map(p=>p.join(' / ')).join(' · '))+'</p></details>'+(last.chains.length?'<table><thead><tr><th>DBA</th><th>'+esc(text('Selected chain','निवडलेली साखळी'))+'</th></tr></thead><tbody>'+last.chains.map(e=>'<tr><td>'+esc(Object.values(e.lords).join(' / '))+'</td><td>'+esc(e.chain.kind+(e.chain.rank?' · '+e.chain.rank+' '+e.chain.ruler:'')+(e.chain.representative?' · representative '+e.chain.representative:'')+' · '+e.chain.segments.length+' sectors')+'</td></tr>').join('')+'</tbody></table>':'')+'</details>';}
